package cn.zhuatech.payroll;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.httpBasic;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class PayrollCalculationApiTests{@Autowired MockMvc mvc;static final String BODY="""
 {"employeeNo":"E-1","currency":"CNY","earnings":[{"code":"BASE","amount":10000,"taxable":true},{"code":"ALLOWANCE","amount":1000,"taxable":false}],"deductions":[{"code":"SOCIAL","amount":1000,"preTax":true},{"code":"OTHER","amount":500,"preTax":false}],"taxBrackets":[{"upToAmount":5000,"rate":0.03},{"upToAmount":20000,"rate":0.10}]}
 """;
 @Test void calculatesGrossProgressiveTaxDeductionsAndNet()throws Exception{mvc.perform(post("/api/advanced/payroll/calculate").with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content(BODY)).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("CALCULATED")).andExpect(jsonPath("$.data.grossPay").value(11000)).andExpect(jsonPath("$.data.tax").value(550)).andExpect(jsonPath("$.data.netPay").value(8950));}
 @Test void requiresAuthentication()throws Exception{mvc.perform(post("/api/advanced/payroll/calculate").contentType(MediaType.APPLICATION_JSON).content(BODY)).andExpect(status().isUnauthorized());}}
